const fs = require("fs");
const src = fs.readFileSync("services/AppSearch.qml", "utf8");
const start = src.indexOf("function fuzzyQuery");
const end = src.indexOf("function _decorateEntry", start);
if (start < 0 || end < 0) process.exit(90);
const block = src.slice(start, end);
if (!block.includes("const scores = new Array(count)")) process.exit(91);
if (!block.includes("scores[index] = Math.min(1.0, score)")) process.exit(92);
if (!block.includes("if (score > root.scoreThreshold)")) process.exit(93);
if (!block.includes("results.push({ entry: entries[index], score: score })")) process.exit(94);

function scoreFor(nameLower, searchLower, base) {
  let score = base;
  if (nameLower.startsWith(searchLower)) score += 0.3;
  else if (nameLower.includes(" " + searchLower) || nameLower.includes("-" + searchLower)) score += 0.15;
  else if (nameLower.includes(searchLower)) score += 0.1;
  return Math.min(1.0, score);
}

function oldCollect(entries, names, searchLower, bases, thresholds, trace) {
  let thresholdIndex = 0;
  return entries.map((obj, index) => {
    const nameLower = names[index] ?? "";
    trace.push("score:" + index);
    const score = scoreFor(nameLower, searchLower, bases[index]);
    return { entry: obj, score };
  }).filter(item => {
    trace.push("threshold:" + item.entry.id);
    const threshold = thresholds[thresholdIndex++ % thresholds.length];
    return item.score > threshold;
  }).sort((a,b)=>b.score-a.score);
}

function newCollect(entries, names, searchLower, bases, thresholds, trace) {
  const count = entries.length;
  const scores = new Array(count);
  for (let index = 0; index < count; ++index) {
    const nameLower = names[index] ?? "";
    trace.push("score:" + index);
    scores[index] = scoreFor(nameLower, searchLower, bases[index]);
  }
  const results = [];
  let thresholdIndex = 0;
  for (let index = 0; index < count; ++index) {
    const score = scores[index];
    trace.push("threshold:" + entries[index].id);
    const threshold = thresholds[thresholdIndex++ % thresholds.length];
    if (score > threshold)
      results.push({ entry: entries[index], score });
  }
  results.sort((a,b)=>b.score-a.score);
  return results;
}

let seed=0x61a55eed>>>0;
function rnd(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed;}
const words=["fire","fox","visual studio","foo-bar","alpha","beta","gamma",""];
for(let c=0;c<50000;c++){
  const n=rnd()%80;
  const entries=new Array(n), names=new Array(n), bases=new Array(n);
  for(let i=0;i<n;i++){
    entries[i]={id:i, marker:(rnd()%7)};
    names[i]=words[rnd()%words.length] + String(rnd()%19);
    const r=rnd()%16;
    bases[i]=r===0?NaN:r===1?Infinity:r===2?-Infinity:((rnd()%2001)-1000)/1000;
  }
  const search=words[rnd()%words.length];
  const thresholds=[];
  const tn=Math.max(1,(rnd()%9)+1);
  for(let i=0;i<tn;i++){
    const tr=rnd()%12;
    thresholds.push(tr===0?NaN:tr===1?Infinity:tr===2?-Infinity:((rnd()%1601)-800)/1000);
  }
  const ta=[],tb=[];
  const a=oldCollect(entries,names,search,bases,thresholds,ta);
  const b=newCollect(entries,names,search,bases,thresholds,tb);
  const norm=x=>x.map(v=>({id:v.entry.id,score:Number.isNaN(v.score)?"NaN":String(v.score)}));
  if(JSON.stringify(norm(a))!==JSON.stringify(norm(b))) process.exit(10);
  if(JSON.stringify(ta)!==JSON.stringify(tb)) process.exit(11);
}
process.exit(0);
